def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8]
    key = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
           if grid[r][c] not in (0, 8)]
    if not cells or not key:
        return out

    # Split the large 8 pattern into its rectangular arms/blocks.
    unseen = set(cells)
    comps = []
    while unseen:
        start = unseen.pop()
        stack = [start]
        comp = [start]
        while stack:
            r, c = stack.pop()
            for p in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if p in unseen:
                    unseen.remove(p)
                    stack.append(p)
                    comp.append(p)
        comps.append(comp)

    # For adjoining arms, use maximal solid rectangles as the natural regions.
    # Each region receives the color of the nearest key marker after matching
    # the key's relative position to the motif's regions.
    regions = []
    remaining = set(cells)
    while remaining:
        r, c = min(remaining)
        best = None
        for r2 in range(r, h):
            for c2 in range(c, w):
                rect = {(a,b) for a in range(r,r2+1) for b in range(c,c2+1)}
                if rect <= remaining and (best is None or len(rect) > len(best)):
                    best = rect
        if best is None:
            best = {(r,c)}
        regions.append(best)
        remaining -= best

    # Color the broad rectangular sections, using their order in the key:
    # the marker pattern determines the corresponding motif-region colors.
    regions.sort(key=lambda s: (min(r for r,c in s), min(c for r,c in s)))
    colors = []
    for r,c,v in key:
        if v not in colors:
            colors.append(v)
    colors.sort(key=lambda v: min((r,c) for r,c,x in key if x == v))
    for i, region in enumerate(regions):
        color = colors[min(i, len(colors)-1)]
        for r,c in region:
            out[r][c] = color
    return out
